import { useForm, type FormErrors } from './useForm';

type Login = { email: string; password: string; remember: boolean };

function validateLogin(v: Login): FormErrors<Login> {
  const errors: FormErrors<Login> = {};
  if (!v.email.includes('@')) errors.email = 'Podaj e-mail';
  if (v.password.length < 8) errors.password = 'Hasło ma co najmniej 8 znaków';
  return errors;
}

export function LoginForm({ onLogin }: { onLogin: (data: Login) => void }) {
  const form = useForm<Login>({ email: '', password: '', remember: false }, validateLogin);

  return (
    <form onSubmit={(e) => { e.preventDefault(); if (form.isValid) onLogin(form.values); }}>
      <label>E-mail <input name="email" value={form.values.email} onChange={form.handleChange} onBlur={form.handleBlur} /></label>
      {form.touched.email && form.errors.email && <p className="error">{form.errors.email}</p>}
      <label>Hasło <input name="password" type="password" value={form.values.password} onChange={form.handleChange} onBlur={form.handleBlur} /></label>
      {form.touched.password && form.errors.password && <p className="error">{form.errors.password}</p>}
      <label><input name="remember" type="checkbox" checked={form.values.remember} onChange={form.handleChange} /> Zapamiętaj mnie</label>
      <button type="submit" disabled={!form.isValid}>Zaloguj</button>
    </form>
  );
}

